/**
 * Catalogue seed — migrated from www.kia-india.com (crawled 4 Oct 2026).
 *
 * This file is the single source for:
 *  - the public site's fallback data when Supabase is not configured, and
 *  - supabase/seed.sql (generated by `npm run db:seed-sql`).
 *
 * Only `import type` is allowed here so the seed script can run under Node's
 * type stripping without path aliases.
 *
 * Content status: spec values are copied verbatim from the legacy spec tables.
 * Descriptions and application copy are edited/drafted from legacy wording and
 * MUST be approved by the client before launch (see docs/CLIENT-APPROVALS.md).
 */
import type {
  AttrDataType,
  LabelValue,
  PublishStatus,
  ResourceType,
} from "../types";

export interface SeedCategory {
  slug: string;
  name: string;
  description: string;
  image_path: string;
  sort_order: number;
  status: PublishStatus;
  seo_title?: string;
  seo_description?: string;
}

export interface SeedAttribute {
  key: string;
  label: string;
  unit: string | null;
  data_type: AttrDataType;
  group_label: string;
  is_key_spec: boolean;
  is_filterable: boolean;
}

export interface SeedModel {
  code: string;
  group: string | null;
  /** attribute key → raw value (number or text) */
  values: Record<string, string | number>;
}

export interface SeedProduct {
  slug: string;
  category: string;
  name: string;
  subtitle: string | null;
  summary: string;
  description_md: string;
  status: PublishStatus;
  is_featured: boolean;
  sort_order: number;
  facets: Record<string, string>;
  highlights: LabelValue[];
  descriptive_specs: LabelValue[];
  standard_equipment: string[];
  optional_extras: string[];
  notes: string[];
  images: { path: string; alt: string }[];
  applications: string[];
  related: string[];
  legacy_path: string | null;
  models: SeedModel[];
}

export interface SeedApplication {
  slug: string;
  name: string;
  summary: string;
  body_md: string;
  image_path: string;
  sort_order: number;
}

export interface SeedResource {
  title: string;
  type: ResourceType;
  description: string | null;
  storage_path: string;
  mime_type: string;
  file_size: number | null;
  issuer: string | null;
  valid_from: string | null;
  valid_to: string | null;
  sort_order: number;
  products: string[];
}

export interface SeedFaq {
  question: string;
  answer_md: string;
  category: string | null;
  product: string | null;
  sort_order: number;
}

