/* ------------------------------------------------------------------ */
/* Engine model tables — verbatim from legacy spec tables               */
/* ------------------------------------------------------------------ */

const ENGINE_COLUMNS = [
  "power_bhp", "power_kw", "speed_rpm", "bore_mm", "stroke_mm", "sfc_g_kwh",
  "fuel_tank_l", "crank_height_mm", "net_weight_kg", "gross_weight_kg", "case_size_cm",
] as const;
const LUBE = "Less than 0.3% of SFC";

type EngineRow = [code: string, ...values: (number | string | null)[]];

function engineModels(group: string, rows: EngineRow[]): SeedModel[] {
  return rows.map(([code, ...vals]) => {
    const values: Record<string, string | number> = { lube_oil: LUBE };
    ENGINE_COLUMNS.forEach((key, i) => {
      const v = vals[i];
      if (v !== null && v !== undefined) values[key] = v;
    });
    return { code, group, values };
  });
}

