const highSpeedSpecs = (): LabelValue[] => [
  { label: "Type", value: "Vertical, four-stroke, constant-speed, stationary, compression-ignition internal combustion engine." },
  { label: "Rotation", value: "Standard rotation is clockwise, facing the flywheel." },
  { label: "Combustion", value: "Open-type combustion chamber in an aluminium-alloy piston." },
  { label: "Bearings", value: "Taper-roller main bearings on single-cylinder and copper-lead bush on double-cylinder engines. Bi-metal alloy big-end bearings; phosphor-bronze valve-rocker and small-end bushes; sintered camshaft bush." },
  { label: "Cylinder head", value: "Cast iron, detachable, designed for adequate cooling." },
  { label: "Gears & drives", value: "Cast-iron timing gears. Power take-off from the flywheel end only." },
  { label: "Fuel system", value: "Gravity feed to the fuel pump." },
  { label: "Lubrication", value: "Force feed to big-end and main bearings — plunger-type oil pump on single-cylinder, gear-type on double-cylinder engines." },
  { label: "Governing", value: "Fixed-speed centrifugal governor mounted on the camshaft gear wheel; speed variation held within limits." },
  { label: "Balancing", value: "Two balance weights bolted to the crankshaft; balanced flywheel for smooth running and long life of moving parts." },
  { label: "Exhaust", value: "Pepper-pot type silencer." },
  { label: "Air cleaner", value: "Oil-bath type or FRITZ paper-felt air cleaner." },
  { label: "Starting", value: "Hand start. A 12 V electric starting system can also be supplied." },
];

const highSpeedOptions = (variant: "air" | "water"): string[] => [
  "Anti-clockwise rotation",
  ...(variant === "air" ? ["Radial (cowling) or axial (blower) cooling"] : []),
  "12 V electric start with alternator for battery charging",
  "Extended crankshaft / extension shaft with coupling in various sizes",
  "Speed variator / variable-speed attachment",
  "Pulleys to buyer's requirements",
  "Oil pressure gauge, hour meter, and auto-stop for low oil pressure and high temperature",
  "Bearing type (taper-roller main bearings, plunger oil pump) or bush type (copper-lead bush, gear oil pump) on single-cylinder engines",
];

